  const options = role === 'operator' ? [['payment_contact', 'ФИО и телефон'], ['card', 'Карта']] : [['merchant', 'Мерчант'], ['bank', 'Банк'], ['card', 'Карта'], ['payment_contact', 'ФИО и телефон'], ['custodian', 'Ответственный']];
