  return <Card className="mt-7 rounded-2xl"><CardHeader><CardTitle>Привязать Telegram и наличные</CardTitle><CardDescription>Telegram username не используется как идентификатор доступа: нужен точный числовой ID.</CardDescription></CardHeader><CardContent>{catalog ? <form className="grid gap-5 md:grid-cols-3" onSubmit={submit}><label className="grid gap-2 text-sm font-medium">Пользователь<Select value={userID} onValueChange={value => { setUserID(value); setCustodianID(''); }}><SelectTrigger><SelectValue placeholder="Выберите пользователя" /></SelectTrigger><SelectContent>{(catalog.users || []).filter(x => x.role === 'collector' || x.role === 'chief').map(x => <SelectItem key={x.id} value={x.id}>{x.name} · {x.role}</SelectItem>)}</SelectContent></Select></label><label className="grid gap-2 text-sm font-medium">Числовой Telegram ID<Input name="telegram_id" inputMode="numeric" required /></label><label className="grid gap-2 text-sm font-medium">Ответственный за наличные<Select value={custodianID} onValueChange={setCustodianID}><SelectTrigger><SelectValue placeholder="Выберите ответственного" /></SelectTrigger><SelectContent>{custodians.map(x => <SelectItem key={x.id} value={x.id}>{x.name}</SelectItem>)}</SelectContent></Select></label><div className="md:col-span-3"><Message error={error} />{message && <Alert className="mt-3"><AlertDescription>{message}</AlertDescription></Alert>}<Button className="mt-4" disabled={busy || !userID || !custodianID}>{busy ? 'Сохранение…' : 'Сохранить связь'}</Button></div></form> : <p>Загрузка…</p>}</CardContent></Card>;
